import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import './Navbar.css';

const NAV_LINKS = [
  { label: 'Home',        to: '/'         },
  { label: 'Apply',       to: '/apply'    },
  { label: 'Outreach',    to: '/outreach' },
  { label: 'FTC Network', to: '/network'  },
  { label: 'Contact',     to: '/contact'  },
];

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const location = useLocation();

  /* Close drawer on route change */
  useEffect(() => { setOpen(false); }, [location.pathname]);

  /* Close drawer on outside click */
  useEffect(() => {
    const handle = (e) => {
      if (!e.target.closest('.dn')) setOpen(false);
    };
    document.addEventListener('mousedown', handle);
    return () => document.removeEventListener('mousedown', handle);
  }, []);

  return (
    <nav className="dn" aria-label="Main navigation">
      <Link to="/" className="dn__logo" aria-label="Duck Robotics — go home">
        DUCK
      </Link>

      {/* Mobile hamburger */}
      <button
        className={`dn__burger${open ? ' open' : ''}`}
        onClick={() => setOpen((v) => !v)}
        aria-label={open ? 'Close navigation menu' : 'Open navigation menu'}
        aria-expanded={open}
      >
        <span /><span /><span />
      </button>

      {/* Link list */}
      <div className={`dn__links${open ? ' open' : ''}`} role="menubar">
        {NAV_LINKS.map(({ label, to }) => (
          <Link
            key={to}
            to={to}
            className={`dn__link${location.pathname === to ? ' dn__link--active' : ''}`}
            role="menuitem"
            aria-current={location.pathname === to ? 'page' : undefined}
          >
            {label}
          </Link>
        ))}
      </div>
    </nav>
  );
}
